import{_ as t,c as a,o,ag as s}from"./chunks/framework.DZ_cNctr.js";const n="/docs/screenshots/annotation-import-menu.png",i="/docs/screenshots/annotation-ndpa.webp",g=JSON.parse('{"title":"Exchanging Annotations","description":"Import annotations from GeoJSON, OME-XML, Aperio XML, ASAP XML and Hamamatsu NDPA, export GeoJSON and OME-XML, and share a slide with its annotations by link.","frontmatter":{"title":"Exchanging Annotations","description":"Import annotations from GeoJSON, OME-XML, Aperio XML, ASAP XML and Hamamatsu NDPA, export GeoJSON and OME-XML, and share a slide with its annotations by link."},"headers":[],"relativePath":"guides/annotation-exchange.md","filePath":"guides/annotation-exchange.md"}'),r={name:"guides/annotation-exchange.md"};function l(h,e,d,p,m,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="exchanging-annotations" tabindex="-1">Exchanging Annotations <a class="header-anchor" href="#exchanging-annotations" aria-label="Permalink to &quot;Exchanging Annotations&quot;">​</a></h1><p>Bring annotations in from other tools, send them back out, and share them with a link.</p><table tabindex="0"><thead><tr><th>Format</th><th>File</th><th>Made by</th><th>Import</th><th>Export</th><th>Opens on</th></tr></thead><tbody><tr><td><a href="#qupath">GeoJSON</a></td><td><code>.geojson</code></td><td>QuPath, Find Nuclei</td><td>Yes</td><td>Yes</td><td>Any image</td></tr><tr><td>OME-XML ROIs</td><td><code>.ome.xml</code></td><td>OME tools, Find Nuclei</td><td>Yes</td><td>Yes</td><td>Any image</td></tr><tr><td><a href="#aperio-imagescope">Aperio XML</a></td><td><code>.xml</code></td><td>Aperio ImageScope</td><td>Yes</td><td>No</td><td>Any slide, made for SVS</td></tr><tr><td><a href="#asap">ASAP XML</a></td><td><code>.xml</code></td><td>ASAP, CAMELYON16 and CAMELYON17</td><td>Yes</td><td>No</td><td>Any slide</td></tr><tr><td><a href="#hamamatsu-ndp-view">Hamamatsu NDPA</a></td><td><code>.ndpa</code></td><td>Hamamatsu NDP.view</td><td>Yes</td><td>No</td><td>NDPI slides only</td></tr></tbody></table><h2 id="share-a-slide-with-its-annotations" tabindex="-1">Share a Slide With Its Annotations <a class="header-anchor" href="#share-a-slide-with-its-annotations" aria-label="Permalink to &quot;Share a Slide With Its Annotations&quot;">​</a></h2><ol><li>Put the slide and the annotation file in storage the viewer can read. See <a href="./remote-urls.html">Remote URLs</a>.</li><li>Open the slide by its address.</li><li>In the <strong>Annotations</strong> panel, click <strong>Import</strong>, then <strong>From web address</strong>, and paste the address of the annotation file.</li><li>Click <strong>Copy link</strong>.</li></ol><p>For private storage, see <a href="./authenticated-sources.html">Private Images and Slides</a>. Behind a token, an annotation file opens with the slide&#39;s token when both sit on the same server.</p><p>The link carries both addresses. Whoever opens it sees the slide with the annotations. Nothing is saved for them until they edit.</p><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><p>In the <strong>Annotations</strong> tab, click <strong>Import</strong>, then <strong>From file</strong> or <strong>From web address</strong>. The viewer reads:</p><img width="850" height="668" src="'+n+'" alt="The Annotations tab with the Import menu open: From file and From web address" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><ul><li><p>GeoJSON, including QuPath exports (<code>.geojson</code>).</p></li><li><p>OME-XML ROIs (<code>.ome.xml</code>).</p></li><li><p>Aperio ImageScope annotations (<code>.xml</code>), for SVS slides.</p></li><li><p>ASAP annotations (<code>.xml</code>), as in the CAMELYON16 and CAMELYON17 challenges.</p></li><li><p>Hamamatsu NDP.view annotations (<code>.ndpa</code>), for NDPI slides. Open the NDPI first: the file stores positions on the glass, and the slide says where it was scanned.</p></li><li><p>Imported shapes show as a contour. Turn on the fill for one shape in the panel.</p></li><li><p>Class names and colours come from the file.</p></li><li><p>A class with no colour gets one colour for the whole class.</p></li><li><p>Each import adds to the shapes on the slide, so several files can sit together. The same file twice adds nothing. <strong>Clear</strong> empties the slide.</p></li></ul><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p><strong>Export GeoJSON</strong> and <strong>Export OME-XML</strong> write the shapes in the slide&#39;s own pixels, at full resolution.</p><p>The GeoJSON is the layout QuPath writes, which 10X Genomics Xenium Explorer reads too. See <a href="#other-tools">Other Tools</a>.</p><h2 id="other-tools" tabindex="-1">Other Tools <a class="header-anchor" href="#other-tools" aria-label="Permalink to &quot;Other Tools&quot;">​</a></h2><h3 id="qupath" tabindex="-1">QuPath <a class="header-anchor" href="#qupath" aria-label="Permalink to &quot;QuPath&quot;">​</a></h3><p>Annotations go both ways, tested with QuPath 0.5.</p><ul><li>From QuPath: <strong>File › Export objects as GeoJSON</strong>, then import the file here.</li><li>Into QuPath: export GeoJSON here, then drag the file onto the slide in QuPath. Shapes, classes and colours come through.</li></ul><h3 id="_10x-genomics-xenium-explorer" tabindex="-1">10X Genomics Xenium Explorer <a class="header-anchor" href="#_10x-genomics-xenium-explorer" aria-label="Permalink to &quot;10X Genomics Xenium Explorer&quot;">​</a></h3><p>Our GeoJSON has the layout 10X Genomics documents for import into Xenium Explorer 4.1 and later: <a href="https://www.10xgenomics.com/support/software/xenium-explorer/latest/tutorials/xe-selecting-multiple-regions-of-interest" target="_blank" rel="noreferrer">Selecting multiple regions of interest</a>. It lists GeoJSON from a third-party tool such as QuPath as a use of its <strong>Import</strong> button. Click <strong>Import</strong> there and pick the file.</p><ul><li><strong>Regions only.</strong> Xenium Explorer takes closed shapes. Lines and points are left out.</li><li><strong>The same image.</strong> Draw on the morphology image or the post-Xenium H&amp;E, so the shapes land in the right place.</li><li><strong>Classes</strong> show as labels in its Annotations layer.</li></ul><h3 id="aperio-imagescope" tabindex="-1">Aperio ImageScope <a class="header-anchor" href="#aperio-imagescope" aria-label="Permalink to &quot;Aperio ImageScope&quot;">​</a></h3><p>Pens, rectangles, ellipses, arrows and rulers open with their names, descriptions and attributes. Import only.</p><h3 id="asap" tabindex="-1">ASAP <a class="header-anchor" href="#asap" aria-label="Permalink to &quot;ASAP&quot;">​</a></h3><p>The outlines of the CAMELYON16 and CAMELYON17 challenges, and other sets drawn in ASAP, open on their slides. Polygons, splines, rectangles, dots, point sets and measurements come in. Each group becomes a class, in the group&#39;s colour. Import only.</p><p>Try it on a public CAMELYON16 lymph node slide. This link opens the slide and the pathologists&#39; two tumour outlines, straight from AWS Open Data:</p><p><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fcamelyon-dataset.s3.amazonaws.com%2FCAMELYON16%2Fimages%2Ftumor_001.tif&amp;ann=https%3A%2F%2Fcamelyon-dataset.s3.amazonaws.com%2FCAMELYON16%2Fannotations%2Ftumor_001.xml" target="_blank" rel="noopener">tumor_001.tif with its tumour outlines</a></p><p>ASAP draws splines as smooth curves. The viewer joins the same points with straight lines, so a spline with few points looks a little more angular here.</p><h3 id="hamamatsu-ndp-view" tabindex="-1">Hamamatsu NDP.view <a class="header-anchor" href="#hamamatsu-ndp-view" aria-label="Permalink to &quot;Hamamatsu NDP.view&quot;">​</a></h3><p>Every NDP.view2 tool opens: freehand lines and regions, rectangles, circles, rulers, pointers, pins and flags, with their titles, details and colours. Import only.</p><img width="1500" height="950" src="'+i+'" alt="CMU-1.ndpi with 11 annotations from an NDP.view2 file: freehand regions, a circle, a rectangle, rulers, pins and pointers, with their names, lengths and areas, listed in the Annotations tab" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><h3 id="visiopharm" tabindex="-1">Visiopharm <a class="header-anchor" href="#visiopharm" aria-label="Permalink to &quot;Visiopharm&quot;">​</a></h3><p>Annotations go both ways, by the formats the <a href="https://cpwebapps.azurewebsites.net/docs/2025.08.1/database/layer_data/" target="_blank" rel="noreferrer">Visiopharm manual</a> lists under Layer Data.</p><ul><li><strong>Into Visiopharm:</strong> export GeoJSON here, then import it in Visiopharm as QuPath GeoJSON.</li><li><strong>From Visiopharm:</strong> export the labels as GeoJSON for Xenium Explorer (<strong>File › Export › LayerData</strong>), then import the file here. Only label objects travel this way, such as segmented cells (<a href="https://visiopharm.com/product-releases/visiopharm-software-updates-2026-02-1/" target="_blank" rel="noreferrer">release notes</a>).</li></ul><p>A file of many cells opens what the viewer can draw and tells you about the rest. See <a href="#cell-detections">Cell Detections</a>.</p><h2 id="cell-detections" tabindex="-1">Cell Detections <a class="header-anchor" href="#cell-detections" aria-label="Permalink to &quot;Cell Detections&quot;">​</a></h2><p>A file with many detected cells opens its annotations and shows a message about the rest. To see large detection results, use <a href="./analytics-format.html">analysis results</a>.</p><h2 id="coordinates" tabindex="-1">Coordinates <a class="header-anchor" href="#coordinates" aria-label="Permalink to &quot;Coordinates&quot;">​</a></h2><p>Coordinates are pixels at full resolution. On <code>.mrxs</code> they start at the top-left of the area holding images, as in QuPath.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses <code>CMU-1.ndpi</code> from the OpenSlide test data, CC0, with an annotation file drawn for this guide in NDP.view2. The ASAP example uses CAMELYON16 <code>tumor_001</code>, CC0. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p>',41)])])}const f=t(r,[["render",l]]);export{g as __pageData,f as default};
